[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body {
    font-family: "Noto Sans Devanagari", sans-serif;
    font-size: 13px;
    margin: 0;
    color: #000;
}

.page-border {
    border: none;
}

.company-row {
    text-align: center;
    padding: 10px 15px 8px 15px;
    border-bottom: none;
}

.company-name {
    font-size: 20px;
    font-weight: bold;
    margin-bottom: 2px;
}

.company-row p {
    margin: 1px 0;
    font-weight: bold;
    font-style: italic;
    font-size: 13px;
}

.info-row {
    display: table;
    width: 100%;
    border-bottom: none;
}

.info-left,
.info-right {
    display: table-cell;
    vertical-align: middle;
    padding: 10px 15px;
}

.info-left {
    width: 60%;
    border-right: none;
}

.info-right {
    width: 40%;
    text-align: right;
    font-weight: bold;
    font-size: 14px;
}

.info-left table {
    border-collapse: collapse;
}

.info-left td {
    padding: 1px 4px;
    vertical-align: top;
    font-style: italic;
    font-weight: bold;
}

.info-left td:first-child {
    white-space: nowrap;
    padding-right: 15px;
}

.title-row {
    text-align: center;
    font-size: 20px;
    font-weight: bold;
    padding: 10px 15px;
}
</style>
</head>

<body>
{%
    set fy = frappe.db.get_value(
        "Fiscal Year",
        {"disabled": 0},
        "year"
    )
%}

<div class="page-border">
    <div class="company-row">
        <div class="company-name">
            नेपाल इकरात इन्जिनियरिङ क. प्रा. लि.
        </div>
        <p>नवलपुर, हेटौडा</p>
        <p>आर्थिक वर्ष {{ fy }}</p>
        <p>आन्तारिक पत्राचार</p>
    </div>

    <div class="info-row">
        <div class="info-left">
            <table>
                <tr>
                    <td>आन्तारिक पत्राचार नं.</td>
                    <td>{{ doc.name }}</td>
                </tr>
                <tr>
                    <td>Date (AD)</td>
                    <td>{{ frappe.utils.formatdate(doc.creation) }}</td>
                </tr>
                <tr>
                    <td>FGs Handover by</td>
                    <td>{{ doc.handerover_by or "" }}</td>
                </tr>
            </table>
        </div>

        <div class="info-right">
            Doc.Ref.No.SF-06
        </div>
    </div>

    <div class="title-row">
        बिक्री योग्य ट्रान्सफर्मरहरूको सूची
    </div>
</div>

</body>
</html>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "transformer", "print_hide": 0, "label": "Transformers", "visible_columns": [{"fieldname": "transformer_serial_no", "print_width": "", "print_hide": 0}, {"fieldname": "serial_no", "print_width": "", "print_hide": 0}, {"fieldname": "item_code", "print_width": "", "print_hide": 0}, {"fieldname": "item_name", "print_width": "", "print_hide": 0}, {"fieldname": "production_plan", "print_width": "", "print_hide": 0}, {"fieldname": "job_order", "print_width": "", "print_hide": 0}, {"fieldname": "kva", "print_width": "", "print_hide": 0}, {"fieldname": "tapping", "print_width": "", "print_hide": 0}, {"fieldname": "tested_date", "print_width": "", "print_hide": 0}, {"fieldname": "tested_by", "print_width": "", "print_hide": 0}, {"fieldname": "change_serial_no", "print_width": "", "print_hide": 0}, {"fieldname": "customer", "print_width": "", "print_hide": 0}, {"fieldname": "status", "print_width": "", "print_hide": 0}, {"fieldname": "remarks", "print_width": "", "print_hide": 0}]}, {"fieldname": "naming_series", "print_hide": 0, "label": "Naming Series"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "handerover_by", "print_hide": 0, "label": "Handover By:"}]
